-- Migration: weekly format (Mon-Wed practice, Thursday puzzle, Sat/Sun checks), regularity bonus and rest days.
-- Safe to run more than once. Run against an existing database after deploying:
--   npx wrangler d1 execute brickfield-db --remote --file=migrations/2026-11-weekly-format.sql
-- Do NOT re-run seed.sql on a live database; it would duplicate every question.

CREATE TABLE IF NOT EXISTS holidays (
  day        TEXT PRIMARY KEY,
  note       TEXT,
  created_at TEXT NOT NULL
);
CREATE TABLE IF NOT EXISTS daily_bonus (
  day        TEXT PRIMARY KEY,
  runs       INTEGER NOT NULL,
  created_at TEXT NOT NULL
);
INSERT OR IGNORE INTO settings(key, value) VALUES ('rest_days', '5');

-- Spare number-sense practice questions become any-week (week 0)
UPDATE questions SET week=0 WHERE kind='practice' AND topic='Number sense' AND prompt='999 + 999 + 999 = ?';
UPDATE questions SET week=0 WHERE kind='practice' AND topic='Number sense' AND prompt='125 × 16 = ?';
UPDATE questions SET week=0 WHERE kind='practice' AND topic='Number sense' AND prompt='37 × 11 = ?';
UPDATE questions SET week=0 WHERE kind='practice' AND topic='Number sense' AND prompt='The digits of a 2-digit number add up to 9. The number is 27 more than the number with its digits reversed. What is the number?';

-- Puzzles that became multiple choice
UPDATE questions SET options='["Rohan","Sid","Tom","Uday"]', answer='3' WHERE kind='puzzle' AND prompt='Batting order: Rohan bats before Sid. Sid bats before Tom. Uday bats after Sid and right before Tom. Who bats third?';
UPDATE questions SET options='["4","6","8","10"]', answer='3' WHERE kind='puzzle' AND prompt='How many rectangles (of any size) are there in a strip of 4 squares in a row?';
UPDATE questions SET options='["Box A","Box B","Box C"]', answer='1' WHERE kind='puzzle' AND prompt='Box A says ''The prize is in here.'' Box B says ''The prize is not in here.'' Box C says ''The prize is not in Box A.'' Exactly one box tells the truth. Where is the prize?';
UPDATE questions SET options='["Thursday","Friday","Saturday","Sunday"]', answer='1' WHERE kind='puzzle' AND prompt='Today is Wednesday. What day will it be 100 days from today?';
UPDATE questions SET options='["7","8","9","10"]', answer='1' WHERE kind='puzzle' AND prompt='A snail climbs 3 m up a 10 m wall each day and slips back 2 m each night. On which day does it reach the top?';

-- Week 1 Saturday/Sunday checks and Mon-Wed practice (copies of diagnostic questions; originals untouched)
INSERT INTO questions(week, kind, topic, difficulty, prompt, answer, options, method) SELECT 1, 'before', 'Patterns', 1, 'What comes next: 2, 6, 12, 20, 30, ___ ?', '42', NULL, 'Gaps grow by 2: +4, +6, +8, +10, +12.' WHERE NOT EXISTS (SELECT 1 FROM questions WHERE kind='before' AND week=1 AND prompt='What comes next: 2, 6, 12, 20, 30, ___ ?');
INSERT INTO questions(week, kind, topic, difficulty, prompt, answer, options, method) SELECT 1, 'before', 'Fractions & decimals', 2, 'Arrange from smallest to largest: 0.6, 5/8, 7/12, 0.65', '1', '["0.6, 5/8, 7/12, 0.65","7/12, 0.6, 5/8, 0.65","7/12, 5/8, 0.6, 0.65","0.6, 7/12, 0.65, 5/8"]', '7/12 ≈ 0.583 and 5/8 = 0.625.' WHERE NOT EXISTS (SELECT 1 FROM questions WHERE kind='before' AND week=1 AND prompt='Arrange from smallest to largest: 0.6, 5/8, 7/12, 0.65');
INSERT INTO questions(week, kind, topic, difficulty, prompt, answer, options, method) SELECT 1, 'before', 'Word problems', 2, 'A batsman scored 45, 62 and 38 in three innings. How many runs must he score in the 4th innings to average 50?', '1', '["50","55","62","45"]', 'He needs 4 × 50 = 200 in total. 200 − 145 = 55.' WHERE NOT EXISTS (SELECT 1 FROM questions WHERE kind='before' AND week=1 AND prompt='A batsman scored 45, 62 and 38 in three innings. How many runs must he score in the 4th innings to average 50?');
INSERT INTO questions(week, kind, topic, difficulty, prompt, answer, options, method) SELECT 1, 'before', 'Number theory', 2, 'What is the smallest number greater than 1 that leaves remainder 1 when divided by 2, 3, 4, 5 or 6?', '61', NULL, 'LCM(2,3,4,5,6) = 60, then add 1.' WHERE NOT EXISTS (SELECT 1 FROM questions WHERE kind='before' AND week=1 AND prompt='What is the smallest number greater than 1 that leaves remainder 1 when divided by 2, 3, 4, 5 or 6?');
INSERT INTO questions(week, kind, topic, difficulty, prompt, answer, options, method) SELECT 1, 'before', 'Logic', 2, 'AB and BA are 2-digit numbers (A and B are digits). AB + BA = 121 and A − B = 5. What is AB?', '83', NULL, 'AB + BA = 11(A + B) = 121, so A + B = 11. With A − B = 5: A = 8, B = 3.' WHERE NOT EXISTS (SELECT 1 FROM questions WHERE kind='before' AND week=1 AND prompt='AB and BA are 2-digit numbers (A and B are digits). AB + BA = 121 and A − B = 5. What is AB?');
INSERT INTO questions(week, kind, topic, difficulty, prompt, answer, options, method) SELECT 1, 'before', 'Counting', 1, 'How many different 3-digit numbers can be made from 1, 2, 3, 4 with no digit repeated?', '1', '["12","24","48","64"]', '4 choices × 3 × 2 = 24.' WHERE NOT EXISTS (SELECT 1 FROM questions WHERE kind='before' AND week=1 AND prompt='How many different 3-digit numbers can be made from 1, 2, 3, 4 with no digit repeated?');
INSERT INTO questions(week, kind, topic, difficulty, prompt, answer, options, method) SELECT 1, 'after', 'Patterns', 2, 'Find 1 + 3 + 5 + 7 + … + 39.', '1', '["380","400","420","780"]', 'There are 20 odd numbers; their sum is 20 × 20.' WHERE NOT EXISTS (SELECT 1 FROM questions WHERE kind='after' AND week=1 AND prompt='Find 1 + 3 + 5 + 7 + … + 39.');
INSERT INTO questions(week, kind, topic, difficulty, prompt, answer, options, method) SELECT 1, 'after', 'Fractions & decimals', 1, '3/4 of a number is 27. What is 2/3 of the same number?', '24', NULL, '1/4 is 9, so the number is 36. 2/3 of 36 = 24.' WHERE NOT EXISTS (SELECT 1 FROM questions WHERE kind='after' AND week=1 AND prompt='3/4 of a number is 27. What is 2/3 of the same number?');
INSERT INTO questions(week, kind, topic, difficulty, prompt, answer, options, method) SELECT 1, 'after', 'Word problems', 1, 'Aarav and Ben have ₹240 altogether. Aarav has ₹40 more than Ben. How much does Ben have (₹)?', '100', NULL, 'Bar model: remove the extra ₹40, then split: (240 − 40) ÷ 2.' WHERE NOT EXISTS (SELECT 1 FROM questions WHERE kind='after' AND week=1 AND prompt='Aarav and Ben have ₹240 altogether. Aarav has ₹40 more than Ben. How much does Ben have (₹)?');
INSERT INTO questions(week, kind, topic, difficulty, prompt, answer, options, method) SELECT 1, 'after', 'Number theory', 3, 'How many whole numbers from 1 to 100 are divisible by 3 or 5 (or both)?', '47', NULL, '33 multiples of 3 + 20 of 5 − 6 of 15 (counted twice) = 47.' WHERE NOT EXISTS (SELECT 1 FROM questions WHERE kind='after' AND week=1 AND prompt='How many whole numbers from 1 to 100 are divisible by 3 or 5 (or both)?');
INSERT INTO questions(week, kind, topic, difficulty, prompt, answer, options, method) SELECT 1, 'after', 'Logic', 2, 'Amit, Bala, Chirag and Dev ran a race. Bala finished behind Amit but ahead of Chirag. Dev finished immediately after Amit. Who finished third?', '1', '["Amit","Bala","Chirag","Dev"]', 'The order must be Amit, Dev, Bala, Chirag.' WHERE NOT EXISTS (SELECT 1 FROM questions WHERE kind='after' AND week=1 AND prompt='Amit, Bala, Chirag and Dev ran a race. Bala finished behind Amit but ahead of Chirag. Dev finished immediately after Amit. Who finished third?');
INSERT INTO questions(week, kind, topic, difficulty, prompt, answer, options, method) SELECT 1, 'after', 'Counting', 2, '8 friends each shake hands once with every other friend. How many handshakes?', '1', '["16","28","56","64"]', 'Each of 8 shakes 7 hands, but each handshake is counted twice: 8 × 7 ÷ 2.' WHERE NOT EXISTS (SELECT 1 FROM questions WHERE kind='after' AND week=1 AND prompt='8 friends each shake hands once with every other friend. How many handshakes?');
INSERT INTO questions(week, kind, topic, difficulty, prompt, answer, options, method) SELECT 1, 'practice', 'Percentage', 1, 'A cricket bat costs ₹800. With a 15% discount, what is the price (₹)?', '680', NULL, 'He pays 85% of 800 = 680.' WHERE NOT EXISTS (SELECT 1 FROM questions WHERE kind='practice' AND week=1 AND prompt='A cricket bat costs ₹800. With a 15% discount, what is the price (₹)?');
INSERT INTO questions(week, kind, topic, difficulty, prompt, answer, options, method) SELECT 1, 'practice', 'Ratio', 2, 'Red and blue bricks are in the ratio 3 : 5. There are 64 bricks. How many more blue bricks than red?', '16', NULL, '8 units = 64, so 1 unit = 8. Blue − red = 2 units = 16.' WHERE NOT EXISTS (SELECT 1 FROM questions WHERE kind='practice' AND week=1 AND prompt='Red and blue bricks are in the ratio 3 : 5. There are 64 bricks. How many more blue bricks than red?');
INSERT INTO questions(week, kind, topic, difficulty, prompt, answer, options, method) SELECT 1, 'practice', 'Speed', 2, 'A car travels 150 km in 2.5 hours. At the same speed, how many hours will 210 km take?', '3.5', NULL, 'Speed = 60 km/h. 210 ÷ 60 = 3.5 hours.' WHERE NOT EXISTS (SELECT 1 FROM questions WHERE kind='practice' AND week=1 AND prompt='A car travels 150 km in 2.5 hours. At the same speed, how many hours will 210 km take?');
INSERT INTO questions(week, kind, topic, difficulty, prompt, answer, options, method) SELECT 1, 'practice', 'Geometry', 2, 'A 12 cm by 8 cm rectangle has a 4 cm × 4 cm square cut from one corner. What is the perimeter of the remaining shape (cm)?', '40', NULL, 'The cut edges just move inward, so the perimeter stays 2 × (12 + 8) = 40.' WHERE NOT EXISTS (SELECT 1 FROM questions WHERE kind='practice' AND week=1 AND prompt='A 12 cm by 8 cm rectangle has a 4 cm × 4 cm square cut from one corner. What is the perimeter of the remaining shape (cm)?');
INSERT INTO questions(week, kind, topic, difficulty, prompt, answer, options, method) SELECT 1, 'practice', 'Geometry', 2, 'One angle of a triangle is 60°. Of the other two angles, one is twice the other. What is the largest angle (degrees)?', '80', NULL, 'The other two share 120° as 1 : 2, so they are 40° and 80°.' WHERE NOT EXISTS (SELECT 1 FROM questions WHERE kind='practice' AND week=1 AND prompt='One angle of a triangle is 60°. Of the other two angles, one is twice the other. What is the largest angle (degrees)?');
INSERT INTO questions(week, kind, topic, difficulty, prompt, answer, options, method) SELECT 1, 'practice', 'Spatial', 3, 'A 3 × 3 × 3 cube is painted on all sides and cut into 27 small cubes. How many small cubes have exactly 2 painted faces?', '12', NULL, 'One cube sits in the middle of each of the 12 edges.' WHERE NOT EXISTS (SELECT 1 FROM questions WHERE kind='practice' AND week=1 AND prompt='A 3 × 3 × 3 cube is painted on all sides and cut into 27 small cubes. How many small cubes have exactly 2 painted faces?');
INSERT INTO questions(week, kind, topic, difficulty, prompt, answer, options, method) SELECT 1, 'practice', 'Heuristics', 2, 'I think of a number, multiply by 3, subtract 7, then divide by 2. I get 10. What was my number?', '9', NULL, 'Work backwards: 10 × 2 = 20, + 7 = 27, ÷ 3 = 9.' WHERE NOT EXISTS (SELECT 1 FROM questions WHERE kind='practice' AND week=1 AND prompt='I think of a number, multiply by 3, subtract 7, then divide by 2. I get 10. What was my number?');
INSERT INTO questions(week, kind, topic, difficulty, prompt, answer, options, method) SELECT 1, 'practice', 'Heuristics', 3, 'A farm has chickens and rabbits: 20 heads and 56 legs. How many rabbits?', '8', NULL, 'If all 20 were chickens: 40 legs. 16 extra legs ÷ 2 extra per rabbit = 8 rabbits.' WHERE NOT EXISTS (SELECT 1 FROM questions WHERE kind='practice' AND week=1 AND prompt='A farm has chickens and rabbits: 20 heads and 56 legs. How many rabbits?');
